/**
 * Local test key material.
 *
 * Generated by Web Crypto in whatever process is running the lab, used once,
 * and never written anywhere. There is no imported key, no certificate, no
 * network fetch and nothing to steal. Two key pairs exist because the lesson
 * needs to separate "this signature is mathematically valid" from "this
 * signature is by the issuer this service provider trusts": the attacker's pair
 * produces the first without the second.
 */
import { hex } from './bytes.js';

export interface SigningKeys {
  readonly privateKey: CryptoKey;
  readonly publicKey: CryptoKey;
  /** SHA-256 over the SubjectPublicKeyInfo, as the learner-visible identifier. */
  readonly fingerprint: string;
  readonly modulusBits: number;
}

const RSA_PARAMS = {
  name: 'RSASSA-PKCS1-v1_5',
  hash: 'SHA-256',
  modulusLength: 2048,
  publicExponent: new Uint8Array([1, 0, 1]),
} as const;

export const WEBCRYPTO_ALGORITHM = { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' } as const;

export async function generateSigningKeys(): Promise<SigningKeys> {
  const pair = await crypto.subtle.generateKey(RSA_PARAMS, true, ['sign', 'verify']);
  const spki = new Uint8Array(await crypto.subtle.exportKey('spki', pair.publicKey));
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', spki));
  return {
    privateKey: pair.privateKey,
    publicKey: pair.publicKey,
    fingerprint: hex(digest),
    modulusBits: RSA_PARAMS.modulusLength,
  };
}

/** Short form of a fingerprint, for table cells. */
export function shortFingerprint(fingerprint: string): string {
  return `${fingerprint.slice(0, 8)}…${fingerprint.slice(-8)}`;
}
